1	package clinical
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"sort"
9		"strings"
10		"time"
11		"unicode/utf8"
12	)
13	
14	// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
15	// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
16	type PackageDelivery struct {
17		ExchangeID ID
18		Status     string
19		Digest     string
20		CreatedAt  time.Time
21		Package    Package
22	}
23	
24	// ReceiptConfirmation 是接收方登记回执后得到的确认。
25	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
26	// 授权失效或患者停用后登记回执也只返回该确认。
27	type ReceiptConfirmation struct {
28		ExchangeID   ID
29		Status       string
30		Outcome      string
31		RegisteredAt time.Time
32	}
33	
34	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
35	// 指定接收方。
36	//
37	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
38	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
39	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
40	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
41	// 夹带无效 UTF-8 字节的请求号、不存在或跨患者的引用、夹带草稿、记录不被绑定
42	// 授权覆盖、授权不符一律拒绝，不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
43	//
44	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
45	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
46	// 更正或有新版本、新增记录都不会改写已创建的包。
47	//
48	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
49	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
50	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
51	// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
52	// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
53	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
54		if !actor.valid() || !actor.IsInternal() {
55			return Exchange{}, ErrAccessDenied
56		}
57		if patientID == "" {
58			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
59		}
60		if strings.TrimSpace(receiverID) == "" {
61			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
62		}
63		if strings.TrimSpace(authorizationID) == "" {
64			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
65		}
66		if strings.TrimSpace(requestID) == "" {
67			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
68		}
69		// 请求号必须是完整合法的 UTF-8：本地快照以 JSON 落盘，encoding/json
70		// 会把无效字节静默替换为 U+FFFD——若放行，重开后保存的请求号与提交时
71		// 不同，原请求号重试找不到原交换，还可能与另一份明确含 U+FFFD 的合法
72		// 请求号撞成同一个。因此夹带任何无效字节或不完整多字节字符的请求号
73		// 一律拒绝，绝不靠替换、截断或跳过坏字节继续创建；用户明确输入的合法
74		// U+FFFD 字符本身是合法 UTF-8，不受此限制。
75		if !utf8.ValidString(requestID) {
76			return Exchange{}, fmt.Errorf("%w: request id must be valid UTF-8", ErrInvalidArgument)
77		}
78		if len(recordIDs) == 0 {
79			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
80		}
81		for _, rid := range recordIDs {
82			if strings.TrimSpace(rid) == "" {
83				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
84			}
85		}
86		wanted := uniqueSortedIDs(recordIDs)
87	
88		var result Exchange
89		err := s.mutate(func(snap *snapshot) error {
90			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
91			// 都只返回原结果（重试不是新建）。
92			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
93				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
94					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
95				}
96				result = *existing
97				if existing.Receipt != nil {
98					r := *existing.Receipt
99					result.Receipt = &r
100				}
101				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
102				// 命中已保存的交换：没有任何状态变更，不落盘——即使本地保存
103				// 条件当前不可用，重试也必须成功返回原交换。
104				return errUnchanged
105			}
106	
107			// 首次创建：患者必须存在且未停用。
108			if _, err := requireActivePatient(snap, patientID); err != nil {
109				return err
110			}
111	
112			// 绑定授权必须存在、属于该患者与接收方、当前有效。
113			a := snap.Authorizations[authorizationID]
114			if a == nil {
115				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
116			}
117			if a.PatientID != patientID {
118				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
119					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
120			}
121			if a.ReceiverID != receiverID {
122				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
123					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
124			}
125			now := s.now()
126			if !a.ActiveAt(now) {
127				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
128				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
129			}
130	
131			// 覆盖只由绑定的这一条授权解释：整类范围或限定范围，与接收方查阅
132			// 共用同一套判定（grantCoverage）。同一接收方的其他授权不并入其中，
133			// 因此不能借用其他授权补足覆盖。
134			coverage := newGrantCoverage()
135			coverage.add(a)
136	
137			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
138			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
139			for _, rid := range wanted {
140				r := snap.Records[rid]
141				if r == nil {
142					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
143				}
144				if r.PatientID != patientID {
145					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
146						ErrMismatchedPatient, rid, r.PatientID, patientID)
147				}
148				if r.CurrentVersionID == "" {
149					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
150						ErrInvalidArgument, rid)
151				}
152				v := snap.Versions[r.CurrentVersionID]
153				if v == nil {
154					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
155				}
156				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
157				// 夹带一条未覆盖记录即整包拒绝，不保存其中合法部分。
158				if !coverage.coversRecord(r) {
159					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
160						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
161				}
162				pkg.Records = append(pkg.Records, PackagedRecord{
163					EncounterID: r.EncounterID,
164					Category:    r.Category,
165					RecordID:    r.ID,
166					VersionID:   v.ID,
167					Version:     v.Number,
168					EffectiveAt: v.CreatedAt,
169					Content:     v.Content,
170				})
171			}
172	
173			x := &Exchange{
174				ID:              newID("exch"),
175				PatientID:       patientID,
176				ReceiverID:      receiverID,
177				AuthorizationID: authorizationID,
178				RequestID:       requestID,
179				CreatorID:       actor.ID,
180				Status:          ExchangePending,
181				Digest:          packageDigest(pkg),
182				Package:         pkg,
183				CreatedAt:       now,
184			}
185			snap.Exchanges[x.ID] = x
186			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
187			result = *x
188			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
189			return nil
190		})
191		return result, err
192	}
193	
194	// FetchPackage 供指定接收方凭交换标识取包。
195	//
196	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
197	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
198	// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
199	// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
200	// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
201	// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
202	// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
203	// 摘要、记录标识或交换状态。
204	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
205	//
206	// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
207	// 重新打包，包内版本与内容仍以创建时保存的为准。
208	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
209		if !actor.valid() || actor.Kind != "receiver" {
210			return PackageDelivery{}, ErrAccessDenied
211		}
212		if strings.TrimSpace(exchangeID) == "" {
213			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
214		}
215	
216		var out PackageDelivery
217		err := s.view(func(snap *snapshot) error {
218			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
219			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
220			// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
221			now := s.now()
222			x := snap.Exchanges[exchangeID]
223			if x == nil || x.ReceiverID != actor.ID {
224				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
225				return ErrAccessDenied
226			}
227			p := snap.Patients[x.PatientID]
228			if p == nil || p.Deactivated {
229				return ErrAccessDenied
230			}
231			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
232			a := snap.Authorizations[x.AuthorizationID]
233			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
234				return ErrAccessDenied
235			}
236			out = PackageDelivery{
237				ExchangeID: x.ID,
238				Status:     x.Status,
239				Digest:     x.Digest,
240				CreatedAt:  x.CreatedAt,
241				Package:    clonePackage(x.Package),
242			}
243			return nil
244		})
245		return out, err
246	}
247	
248	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
249	// 包摘要、接受或拒绝的结果及原因。
250	//
251	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
252	// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
253	// 状态不变。相同回执（结果与原因均相同）重交只是确认已保存的那份回执：
254	// 返回原确认（登记时间保持首次成功登记时的值），不新增审计、不改写已保存
255	// 数据，也不触发落盘——即使本地保存条件当前不可用，重交仍成功返回原确认；
256	// 结果或原因改变返回 ErrConflict，与当前能否保存无关。其他身份不能代交，
257	// 不存在的交换统一拒绝。
258	//
259	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
260	// 不提供任何受保护内容。
261	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
262		if !actor.valid() || actor.Kind != "receiver" {
263			return ReceiptConfirmation{}, ErrAccessDenied
264		}
265		if strings.TrimSpace(exchangeID) == "" {
266			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
267		}
268		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
269			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
270		}
271		if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
272			return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
273		}
274		if outcome == ReceiptAccepted {
275			// 接受不携带原因；统一归一化，保证重复提交判定稳定。
276			reason = ""
277		}
278	
279		var conf ReceiptConfirmation
280		err := s.mutate(func(snap *snapshot) error {
281			x := snap.Exchanges[exchangeID]
282			if x == nil || x.ReceiverID != actor.ID {
283				// 不存在或属于其他接收方/其他身份：统一拒绝。
284				return ErrAccessDenied
285			}
286			if digest != x.Digest {
287				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
288			}
289			if x.Receipt != nil {
290				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
291					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
292				}
293				// 相同回执重交：只是确认已保存的那份回执，没有任何状态变更，
294				// 不落盘——即使本地保存条件当前不可用，也成功返回原确认，
295				// 登记时间保持首次成功登记时的值。
296				conf = ReceiptConfirmation{
297					ExchangeID:   x.ID,
298					Status:       x.Status,
299					Outcome:      x.Receipt.Outcome,
300					RegisteredAt: x.Receipt.RegisteredAt,
301				}
302				return errUnchanged
303			}
304	
305			now := s.now()
306			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
307			if outcome == ReceiptAccepted {
308				x.Status = ExchangeAccepted
309			} else {
310				x.Status = ExchangeRejected
311			}
312			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
313			conf = ReceiptConfirmation{
314				ExchangeID:   x.ID,
315				Status:       x.Status,
316				Outcome:      outcome,
317				RegisteredAt: now,
318			}
319			return nil
320		})
321		return conf, err
322	}
323	
324	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
325	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
326	// ErrMismatchedPatient。
327	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
328		if !actor.valid() || !actor.IsInternal() {
329			return Exchange{}, ErrAccessDenied
330		}
331		var result Exchange
332		err := s.view(func(snap *snapshot) error {
333			x, err := requireExchange(snap, patientID, exchangeID)
334			if err != nil {
335				return err
336			}
337			result = cloneExchangeValue(x)
338			return nil
339		})
340		return result, err
341	}
342	
343	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
344	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
345	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
346		if !actor.valid() || !actor.IsInternal() {
347			return nil, ErrAccessDenied
348		}
349		var result []Exchange
350		err := s.view(func(snap *snapshot) error {
351			if _, err := requirePatient(snap, patientID); err != nil {
352				return err
353			}
354			for _, x := range snap.Exchanges {
355				if x.PatientID == patientID {
356					result = append(result, cloneExchangeValue(x))
357				}
358			}
359			sort.Slice(result, func(i, j int) bool {
360				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
361					return result[i].CreatedAt.Before(result[j].CreatedAt)
362				}
363				return result[i].ID < result[j].ID
364			})
365			return nil
366		})
367		return result, err
368	}
369	
370	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
371		x := snap.Exchanges[exchangeID]
372		if x == nil {
373			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
374		}
375		if x.PatientID != patientID {
376			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
377				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
378		}
379		return x, nil
380	}
381	
382	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
383		for _, x := range snap.Exchanges {
384			if x.CreatorID == creatorID && x.RequestID == requestID {
385				return x
386			}
387		}
388		return nil
389	}
390	
391	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
392	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
393		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
394			return false
395		}
396		if len(x.Package.Records) != len(wantedRecordIDs) {
397			return false
398		}
399		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
400		for i, pr := range x.Package.Records {
401			if pr.RecordID != wantedRecordIDs[i] {
402				return false
403			}
404		}
405		return true
406	}
407	
408	func uniqueSortedIDs(ids []ID) []ID {
409		seen := make(map[ID]struct{}, len(ids))
410		out := make([]ID, 0, len(ids))
411		for _, id := range ids {
412			if _, ok := seen[id]; ok {
413				continue
414			}
415			seen[id] = struct{}{}
416			out = append(out, id)
417		}
418		sort.Strings(out)
419		return out
420	}
421	
422	func clonePackage(p Package) Package {
423		p.Records = append([]PackagedRecord(nil), p.Records...)
424		return p
425	}
426	
427	func cloneExchangeValue(x *Exchange) Exchange {
428		y := *x
429		y.Package = clonePackage(x.Package)
430		if x.Receipt != nil {
431			r := *x.Receipt
432			y.Receipt = &r
433		}
434		return y
435	}
436	
437	// canonicalRecord 固定摘要中每个字段的序列化顺序。
438	type canonicalRecord struct {
439		EncounterID ID     `json:"encounter_id"`
440		Category    string `json:"category"`
441		RecordID    ID     `json:"record_id"`
442		VersionID   ID     `json:"version_id"`
443		Version     int    `json:"version"`
444		EffectiveAt string `json:"effective_at"`
445		Content     string `json:"content"`
446	}
447	
448	type canonicalPackage struct {
449		PatientID  ID                `json:"patient_id"`
450		ReceiverID string            `json:"receiver_id"`
451		Records    []canonicalRecord `json:"records"`
452	}
453	
454	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
455	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
456	func packageDigest(p Package) string {
457		cp := canonicalPackage{
458			PatientID:  p.PatientID,
459			ReceiverID: p.ReceiverID,
460			Records:    make([]canonicalRecord, 0, len(p.Records)),
461		}
462		recs := append([]PackagedRecord(nil), p.Records...)
463		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
464		for _, r := range recs {
465			cp.Records = append(cp.Records, canonicalRecord{
466				EncounterID: r.EncounterID,
467				Category:    r.Category,
468				RecordID:    r.RecordID,
469				VersionID:   r.VersionID,
470				Version:     r.Version,
471				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
472				Content:     r.Content,
473			})
474		}
475		raw, err := json.Marshal(cp)
476		if err != nil {
477			// 参与序列化的都是字符串/整数等基础类型，不应失败。
478			panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
479		}
480		sum := sha256.Sum256(raw)
481		return hex.EncodeToString(sum[:])
482	}
483

