// 一律 ErrInvalidArgument，不返回交换标识，不新增交换或交换创建审计，
// 不占用请求号；关闭重开后交换清单与审计仍是拒绝前的结果。
func TestCreateExchangeRejectsInvalidUTF8RequestID(t *testing.T) {
	for _, tc := range invalidRequestIDs {
		t.Run(tc.label, func(t *testing.T) {
			dir := t.TempDir()
			clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
			open := func() *Store {
				s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
				if err != nil {
					t.Fatalf("open: %v", err)
				}
				return s
			}

			s := open()
			f := setupExchangeUTF8(t, s, clk)
			auditBefore := mustAudit(t, s, f.pid)

			x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, tc.requestID)
			if !errors.Is(err, ErrInvalidArgument) {
				t.Fatalf("CreateExchange(%q) err = %v, want ErrInvalidArgument", tc.requestID, err)
			}
			if x.ID != "" {
				t.Fatalf("rejected create returned exchange id %q", x.ID)
			}
			// 拒绝不能留下交换或交换创建审计。
			xs, err := s.ListExchanges(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if len(xs) != 0 {
				t.Fatalf("rejected create left exchanges: %+v", xs)
			}
			audit, err := s.AuditEvents(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(audit, auditBefore) {
				t.Fatalf("audit changed after rejected create")
			}

			// 坏字节没有落盘：关闭重开后交换清单与审计仍是拒绝前的结果。
			s = reopenStore(t, s, dir, clk)
			xs, err = s.ListExchanges(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if len(xs) != 0 {
				t.Fatalf("rejected create persisted after reopen: %+v", xs)
			}
			audit, err = s.AuditEvents(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(audit, auditBefore) {
				t.Fatalf("audit changed after reopen")
			}

			// 被拒绝的请求号不被占用：坏字节不会被替换成某个合法请求号去
			// 命中或占用它——随后用对应的合法形式可以正常创建。
			clean := "req-clean-after-reject"
			if _, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, clean); err != nil {
				t.Fatalf("create after rejection: %v", err)
			}
			_ = s.Close()
		})
	}

	// 空串与全空白请求号继续按既有规则拒绝。
	s, clk := newTestStore(t)
	f := setupExchangeUTF8(t, s, clk)
	for _, blank := range []string{"", " ", "\n\t\r ", "　"} {
		if _, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, blank); !errors.Is(err, ErrInvalidArgument) {
			t.Fatalf("CreateExchange blank request id %q err = %v, want ErrInvalidArgument", blank, err)
		}
	}
	xs, err := s.ListExchanges(doc, f.pid)
	if err != nil {
		t.Fatal(err)
	}
	if len(xs) != 0 {
		t.Fatalf("blank request ids left exchanges: %+v", xs)
	}
}

// TestCreateExchangeValidUTF8RequestIDPreservedRoundTrip 覆盖合法请求号：
// 原样保存与比较，不统一字符形态、不去首尾空白；当次与关闭重开后看到的
// 请求号逐字相同，同一使用者以相同请求号与相同参数重试仍返回原交换。
func TestCreateExchangeValidUTF8RequestIDPreservedRoundTrip(t *testing.T) {
	for _, tc := range validRequestIDs {
		t.Run(tc.label, func(t *testing.T) {
			dir := t.TempDir()
			clk := &fakeClock{t: time.Date(2026, 6, 2, 9, 0, 0, 0, time.UTC)}
			open := func() *Store {
				s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
				if err != nil {
					t.Fatalf("open: %v", err)
				}
				return s
			}

			s := open()
			f := setupExchangeUTF8(t, s, clk)

			x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, tc.requestID)
			if err != nil {
				t.Fatalf("CreateExchange(%q): %v", tc.requestID, err)
			}
			if x.RequestID != tc.requestID {
				t.Fatalf("returned request id = %q, want %q", x.RequestID, tc.requestID)
			}

			// 相同请求号与相同参数重试：返回原交换，不新增交换或审计。
			auditBefore := mustAudit(t, s, f.pid)
			again, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, tc.requestID)
			if err != nil {
				t.Fatalf("retry: %v", err)
			}
			if again.ID != x.ID || again.RequestID != tc.requestID {
				t.Fatalf("retry returned %+v, want exchange %q", again, x.ID)
			}
			if got := exchangedAuditCount(mustAudit(t, s, f.pid)); got != exchangedAuditCount(auditBefore) {
				t.Fatalf("retry added an exchange audit event")
			}

			// 关闭后从同一位置重新打开：请求号逐字保持，重试仍命中同一份。
			s = reopenStore(t, s, dir, clk)
			t.Cleanup(func() { _ = s.Close() })
			xs, err := s.ListExchanges(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if len(xs) != 1 || xs[0].RequestID != tc.requestID {
				t.Fatalf("exchanges after reopen = %+v, want one with request id %q", xs, tc.requestID)
			}
			again, err = s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, tc.requestID)
			if err != nil {
				t.Fatalf("retry after reopen: %v", err)
			}
			if again.ID != x.ID {
				t.Fatalf("retry after reopen returned exchange %q, want %q", again.ID, x.ID)
			}
			xs, err = s.ListExchanges(doc, f.pid)
			if err != nil {
				t.Fatal(err)
			}
			if len(xs) != 1 {
				t.Fatalf("retry after reopen created another exchange: %+v", xs)
			}
		})
	}
}

// TestCreateExchangeInvalidRequestIDDoesNotHitReplacementCharExchange 覆盖
// 撞号场景：已存在明确包含合法 U+FFFD 的请求号时，夹带非法字节的请求号
// 不能被替换后命中那份旧交换，也不能另建一份让两者重开后变成同一个请求号。
func TestCreateExchangeInvalidRequestIDDoesNotHitReplacementCharExchange(t *testing.T) {
	dir := t.TempDir()
	clk := &fakeClock{t: time.Date(2026, 6, 3, 9, 0, 0, 0, time.UTC)}
	open := func() *Store {
		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
		if err != nil {
			t.Fatalf("open: %v", err)
		}
		return s
	}

	s := open()
	f := setupExchangeUTF8(t, s, clk)

	// 用户明确输入合法 U+FFFD 的请求号可以正常创建。
	explicit := "请求-�"
	x1, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, explicit)
	if err != nil {
		t.Fatalf("create with explicit U+FFFD: %v", err)
	}

	// 夹带非法字节的请求号（替换后会变成 explicit）必须被拒绝，而不是
	// 命中或另建：返回 ErrInvalidArgument，交换清单与审计不变。
	auditBefore := mustAudit(t, s, f.pid)
	if _, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "请求-\xff"); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("invalid utf8 request id err = %v, want ErrInvalidArgument", err)
	}
	xs, err := s.ListExchanges(doc, f.pid)
	if err != nil {
		t.Fatal(err)
	}
	if len(xs) != 1 || xs[0].ID != x1.ID || xs[0].RequestID != explicit {
		t.Fatalf("exchanges after rejected create = %+v, want only %q", xs, explicit)
	}
	audit, err := s.AuditEvents(doc, f.pid)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(audit, auditBefore) {
		t.Fatalf("audit changed after rejected create")
	}

	// 关闭重开后仍只有那一份明确含 U+FFFD 的交换，请求号逐字相同；
	// 用明确输入的合法请求号重试仍稳定返回它。
	s = reopenStore(t, s, dir, clk)
	t.Cleanup(func() { _ = s.Close() })
	xs, err = s.ListExchanges(doc, f.pid)
	if err != nil {
		t.Fatal(err)
	}
	if len(xs) != 1 || xs[0].ID != x1.ID || xs[0].RequestID != explicit {
		t.Fatalf("exchanges after reopen = %+v, want only %q", xs, explicit)
	}
	again, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, explicit)
	if err != nil {
		t.Fatalf("retry explicit U+FFFD after reopen: %v", err)
	}
	if again.ID != x1.ID {
		t.Fatalf("retry after reopen returned exchange %q, want %q", again.ID, x1.ID)
	}
}

// TestCreateExchangeRequestIDRetrySemanticsPreserved 保证合法请求号的既有
// 重复提交行为不变：相同参数重试返回原交换，参数变化返回 ErrConflict，
// 不同内部使用者的请求号互不占用。
func TestCreateExchangeRequestIDRetrySemanticsPreserved(t *testing.T) {
	s, clk := newTestStore(t)
	f := setupExchangeUTF8(t, s, clk)

	x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-语义")
	if err != nil {
		t.Fatal(err)
	}

	// 相同请求号 + 相同参数（记录集合排列变化不算参数变化）：返回原交换。
	again, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid, f.rid}, "req-语义")
	if err != nil {
		t.Fatalf("same-params retry: %v", err)
	}
	if again.ID != x.ID {
		t.Fatalf("same-params retry returned %q, want %q", again.ID, x.ID)
	}

	// 相同请求号改用其他参数：ErrConflict。
	if _, err := s.CreateExchange(doc, f.pid, rcvB.ID, f.auth.ID, []ID{f.rid}, "req-语义"); !errors.Is(err, ErrConflict) {
		t.Fatalf("different-params retry err = %v, want ErrConflict", err)
	}

	// 不同内部使用者的同一请求号互不占用。
	other, err := s.CreateExchange(doc2, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-语义")
	if err != nil {
		t.Fatalf("other creator with same request id: %v", err)
	}
	if other.ID == x.ID {
		t.Fatalf("different creators must not share request id %q", "req-语义")
	}
}

package clinical

import (
	"errors"
	"time"
)

// 记录类别：诊断与医嘱。
const (
	Diagnosis = "diagnosis"
	Order     = "order"
)

// 审计动作。
const (
	ActionActivated   = "activated"
	ActionCorrected   = "corrected"
	ActionGranted     = "authorization_granted"
	ActionRevoked     = "authorization_revoked"
	ActionDeactivated = "patient_deactivated"
	ActionExchanged   = "exchange_created"
	ActionReceipted   = "receipt_registered"
)

// 合成数据标记。本包只处理合成患者资料，登记时统一写入。
const SyntheticSource = "synthetic"

// 调用方身份。Internal 为内部使用者，Receiver 为接收方。
//
// 内部使用者可查看全部草稿与完整历史、建立与撤回授权、维护档案；
// 接收方只能凭有效授权读取当前生效版本。
type Actor struct {
	ID   string
	Kind string // "internal" 或 "receiver"
}

// InternalActor 构造一个内部使用者身份。
func InternalActor(id string) Actor { return Actor{ID: id, Kind: "internal"} }

// ReceiverActor 构造一个接收方身份。
func ReceiverActor(id string) Actor { return Actor{ID: id, Kind: "receiver"} }

// IsInternal 报告该身份是否为内部使用者。
func (a Actor) IsInternal() bool { return a.Kind == "internal" }

func (a Actor) valid() bool {
	if a.ID == "" {
		return false
	}
	return a.Kind == "internal" || a.Kind == "receiver"
}

// ID 是患者、就诊、记录、版本、授权与审计事件的稳定标识。
// ID 在各自类型的集合内唯一，由登记操作生成并原样返回，
// 关闭后从同一位置重新打开仍然有效。
type ID = string

// Patient 是一名合成患者的档案。
type Patient struct {
	ID          ID
	Name        string
	Source      string // 始终为 SyntheticSource
	Deactivated bool
	CreatedAt   time.Time
}

// Encounter 是患者的一次就诊。
type Encounter struct {
	ID         ID
	PatientID  ID
	OccurredAt time.Time
	CreatedAt  time.Time
}

// Version 是一条记录在某一时刻被固化的完整内容。
// 生效产生第 1 版；每次更正产生新版本并通过 PrevID 链接到上一版本。
type Version struct {
	ID        ID
	RecordID  ID
	Number    int
	Content   string
	Category  string
	CreatedAt time.Time // 生效或更正发生的时间
	PrevID    ID        // 上一版本；第 1 版为空
	Reason    string    // 更正原因；第 1 版为空
}

// Record 是一条诊断或医嘱。它在草稿与版本之间推进：
// 草稿可反复修改或删除；生效后产生不可变的当前版本，
// 此后只能通过更正产生新版本，不能被直接覆盖或删除。
type Record struct {
	ID          ID
	PatientID   ID
	EncounterID ID
	Category    string

	DraftContent string
	HasDraft     bool

	CurrentVersionID ID
	Versions         []ID // 按版本号顺序，旧到新
}

// Authorization 是内部使用者为一名接收方建立的、针对某患者的读取授权。
// 范围由两类条目组成，二者可并存、均可覆盖多条就诊与类别：
//
//   - Scopes：整类范围，覆盖某次就诊下某个类别（诊断/医嘱）的全部已生效
//     记录，含授权建立之后才生效的记录；读取时始终取记录的当前生效版本。
//   - Selections：限定范围，仅覆盖明确选出的具体记录。被选记录被更正后
//     授权覆盖它的当前版本；但同一就诊同一类别的其他记录、以及后来新增
//     并生效的记录都不会自动进入限定范围。
//
// 授权仅在 [StartsAt, ExpiresAt) 内有效。
type Authorization struct {
	ID         ID
	PatientID  ID
	ReceiverID string
	Scopes     []Scope
	// Selections 为限定范围中明确选出的记录。为空表示该授权只有整类范围；
	// 旧数据与 Grant 建立的授权该字段始终为空。
	Selections []RecordSelection
	StartsAt   time.Time
	ExpiresAt  time.Time
	RevokedAt  *time.Time // 撤回时间；nil 表示未撤回
	CreatedAt  time.Time
}

// ActiveAt 报告授权在时刻 t 是否有效：已开始、未到期、未撤回。
// 开始时刻即生效；到截止时刻立即失效（半开区间 [StartsAt, ExpiresAt)）。
func (a *Authorization) ActiveAt(t time.Time) bool {
	if a.RevokedAt != nil {
		return false
	}
	if t.Before(a.StartsAt) {
		return false
	}
	if !t.Before(a.ExpiresAt) {
		return false
	}
	return true
}

// Scope 是授权范围中的一项：某次就诊下的某个记录类别。
type Scope struct {
	EncounterID ID
	Category    string
}

// RecordSelection 是授权限定范围中的一项：明确选出某条已生效记录，
// 并声明它所属的就诊与类别。建立授权时记录必须存在、已生效、属于该
// 患者，且其实际就诊与类别必须与声明一致；同一记录在一条授权内重复
// 选择只算一次。
type RecordSelection struct {
	EncounterID ID
	Category    string
	RecordID    ID
}

// AuditEvent 是一条仅供内部使用者按患者查看的审计事件。
type AuditEvent struct {
	ID         ID
	PatientID  ID
	ActorID    string
	Action     string
	ObjectType string
	ObjectID   ID
	OccurredAt time.Time
}

// ReadResult 是接收方一次受限读取得到的内容。
type ReadResult struct {
	EncounterID ID
	Category    string
	// Records 为该就诊该类别下、当前生效且被有效授权覆盖的记录，
	// 每项只含当前生效版本的完整内容，不含草稿、旧版本或更正原因。
	Records []EffectiveRecord
}

// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// 交换状态：创建后待回执，接收方登记回执后转为已接受或已拒绝。
const (
	ExchangePending  = "pending_receipt"
	ExchangeAccepted = "accepted"
	ExchangeRejected = "rejected"
)

// 回执结果：接受或拒绝打包内容。
const (
	ReceiptAccepted = "accepted"
	ReceiptRejected = "rejected"
)

// PackagedRecord 是包内固化的一条记录版本。包在创建时取各记录的当前生效
// 版本快照：此后记录被更正或新增版本都不会改写包内容。
//
// 只含核对所需的标识、版本号、生效时间与完整内容，不含患者姓名、草稿、
// 历史版本或更正原因（Version.Reason）。
type PackagedRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// Package 是一份已固化的交换内容：只含患者与接收方标识及各记录的版本快照。
type Package struct {
	PatientID  ID
	ReceiverID string
	Records    []PackagedRecord
}

// Receipt 是接收方对一份包的回执。接受时 Reason 为空；拒绝时 Reason 必填。
type Receipt struct {
	Outcome      string
	Reason       string
	RegisteredAt time.Time
}

// Exchange 是把已授权记录打包给指定接收方的一次交换。
//
// 创建即把当时的当前版本固化进 Package 并计算摘要；状态初始为待回执。
// 请求号（RequestID）按发起的内部使用者区分，用于安全重试：同一使用者以
// 相同请求号、患者、接收方、绑定授权与记录集合重试时返回原交换。
type Exchange struct {
	ID              ID
	PatientID       ID
	ReceiverID      string
	AuthorizationID ID
	RequestID       string
	CreatorID       string // 创建交换的内部使用者标识
	Status          string // ExchangePending/Accepted/Rejected
	Digest          string // 包内容摘要，接收方回执时须原样回传
	Package         Package
	Receipt         *Receipt
	CreatedAt       time.Time
}

// 失败一律返回明确错误，不留下半条记录。
var (
	// ErrNotFound 表示引用的患者、就诊、记录、版本或授权不存在。
	ErrNotFound = errors.New("clinical: referenced object not found")
	// ErrMismatchedPatient 表示混用了属于不同患者的对象。
	ErrMismatchedPatient = errors.New("clinical: objects belong to different patients")
	// ErrInvalidArgument 表示参数本身不合法（空内容、空范围、时间窗倒置等）。
	ErrInvalidArgument = errors.New("clinical: invalid argument")
	// ErrConflict 表示乐观并发冲突：指定的版本已不再是当前版本。
	ErrConflict = errors.New("clinical: version conflict")
	// ErrDeactivated 表示患者档案已停用，该写操作不再允许。
	ErrDeactivated = errors.New("clinical: patient record is deactivated")
	// ErrActive 表示记录已有生效版本，不能按草稿方式直接覆盖或删除。
	ErrActive = errors.New("clinical: record is already effective")
	// ErrAccessDenied 表示接收方没有覆盖所请求范围的有效授权，
	// 或内部规则不允许该身份执行此操作。返回时不携带任何受保护内容。
	ErrAccessDenied = errors.New("clinical: access denied")
	// ErrClosed 表示 Store 已关闭。
	ErrClosed = errors.New("clinical: store closed")
)

