121	// 授权、不新增授权创建审计；关闭重开后授权清单与审计仍是拒绝前的结果。
122	func TestGrantRejectsInvalidUTF8ReceiverID(t *testing.T) {
123		for _, tc := range invalidReceiverIDs {
124			t.Run(tc.label, func(t *testing.T) {
125				dir := t.TempDir()
126				clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
127				open := func() *Store {
128					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
129					if err != nil {
130						t.Fatalf("open: %v", err)
131					}
132					return s
133				}
134	
135				s := open()
136				f := setupGrantUTF8(t, s)
137				st := clk.t.Add(-time.Hour)
138				en := clk.t.Add(24 * time.Hour)
139				scopes := []Scope{{EncounterID: f.eid, Category: Diagnosis}}
140				selections := []RecordSelection{{RecordID: f.rid, EncounterID: f.eid, Category: Diagnosis}}
141	
142				// 整类授权（Grant 公开入口）。
143				auditBefore := mustAudit(t, s, f.pid)
144				a, err := s.Grant(doc, f.pid, tc.receiverID, scopes, st, en)
145				checkGrantRejected(t, s, f, a, err, auditBefore)
146	
147				// 限定记录授权。
148				a, err = s.GrantSelective(doc, f.pid, tc.receiverID, nil, selections, st, en)
149				checkGrantRejected(t, s, f, a, err, auditBefore)
150	
151				// 整类与限定混合的授权。
152				a, err = s.GrantSelective(doc, f.pid, tc.receiverID, scopes, selections, st, en)
153				checkGrantRejected(t, s, f, a, err, auditBefore)
154	
155				// 坏字节没有落盘：关闭重开后授权清单与审计仍是拒绝前的结果。
156				s = reopenStore(t, s, dir, clk)
157				auths, err := s.ListAuthorizations(doc, f.pid, "")
158				if err != nil {
159					t.Fatal(err)
160				}
161				if len(auths) != 0 {
162					t.Fatalf("rejected grant persisted after reopen: %+v", auths)
163				}
164				audit, err := s.AuditEvents(doc, f.pid)
165				if err != nil {
166					t.Fatal(err)
167				}
168				if !reflect.DeepEqual(audit, auditBefore) {
169					t.Fatalf("audit changed after reopen")
170				}
171	
172				// 被拒绝的坏标识不影响随后的合法授权：用合法标识可以正常创建。
173				if _, err := s.Grant(doc, f.pid, "rcv-clean-after-reject", scopes, st, en); err != nil {
174					t.Fatalf("grant after rejection: %v", err)
175				}
176				_ = s.Close()
177			})
178		}
179	}
180	
181	// TestGrantValidUTF8ReceiverIDPreservedRoundTrip 覆盖合法接收方标识：原样
182	// 保存与精确匹配，不裁剪首尾空白、不改写字符形态；创建返回值、单条查询与
183	// 关闭重开后的清单中接收方标识逐字相同，按接收方筛选与接收方读取都只匹配
184	// 完全相同的标识。
185	func TestGrantValidUTF8ReceiverIDPreservedRoundTrip(t *testing.T) {
186		for _, tc := range validReceiverIDs {
187			t.Run(tc.label, func(t *testing.T) {
188				dir := t.TempDir()
189				clk := &fakeClock{t: time.Date(2026, 6, 2, 9, 0, 0, 0, time.UTC)}
190				open := func() *Store {
191					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
192					if err != nil {
193						t.Fatalf("open: %v", err)
194					}
195					return s
196				}
197	
198				s := open()
199				f := setupGrantUTF8(t, s)
200				st := clk.t.Add(-time.Hour)
201				en := clk.t.Add(24 * time.Hour)
202				scopes := []Scope{{EncounterID: f.eid, Category: Diagnosis}}
203	
204				a, err := s.Grant(doc, f.pid, tc.receiverID, scopes, st, en)
205				if err != nil {
206					t.Fatalf("Grant(%q): %v", tc.receiverID, err)
207				}
208				if a.ReceiverID != tc.receiverID {
209					t.Fatalf("returned receiver id = %q, want %q", a.ReceiverID, tc.receiverID)
210				}
211	
212				// 单条查询：接收方标识逐字相同。
213				got, err := s.GetAuthorization(doc, f.pid, a.ID)
214				if err != nil {
215					t.Fatal(err)
216				}
217				if got.ReceiverID != tc.receiverID {
218					t.Fatalf("GetAuthorization receiver id = %q, want %q", got.ReceiverID, tc.receiverID)
219				}
220	
221				// 按接收方筛选：只匹配完全相同的标识。
222				auths, err := s.ListAuthorizations(doc, f.pid, tc.receiverID)
223				if err != nil {
224					t.Fatal(err)
225				}
226				if len(auths) != 1 || auths[0].ID != a.ID || auths[0].ReceiverID != tc.receiverID {
227					t.Fatalf("list by receiver = %+v, want only %q", auths, tc.receiverID)
228				}
229	
230				// 接收方读取：以原标识身份可以读到授权内容。
231				res, err := s.Read(ReceiverActor(tc.receiverID), f.pid, f.eid, Diagnosis)
232				if err != nil {
233					t.Fatalf("read as receiver: %v", err)
234				}
235				if len(res.Records) != 1 || res.Records[0].RecordID != f.rid {
236					t.Fatalf("read records = %+v, want record %q", res.Records, f.rid)
237				}
238	
239				// 关闭后从同一位置重新打开：清单中的接收方标识逐字保持，
240				// 筛选与读取仍只认原标识。
241				s = reopenStore(t, s, dir, clk)
242				t.Cleanup(func() { _ = s.Close() })
243				auths, err = s.ListAuthorizations(doc, f.pid, tc.receiverID)
244				if err != nil {
245					t.Fatal(err)
246				}
247				if len(auths) != 1 || auths[0].ID != a.ID || auths[0].ReceiverID != tc.receiverID {
248					t.Fatalf("list after reopen = %+v, want only %q", auths, tc.receiverID)
249				}
250				got, err = s.GetAuthorization(doc, f.pid, a.ID)
251				if err != nil {
252					t.Fatal(err)
253				}
254				if got.ReceiverID != tc.receiverID {
255					t.Fatalf("GetAuthorization after reopen receiver id = %q, want %q", got.ReceiverID, tc.receiverID)
256				}
257				if _, err := s.Read(ReceiverActor(tc.receiverID), f.pid, f.eid, Diagnosis); err != nil {
258					t.Fatalf("read as receiver after reopen: %v", err)
259				}
260			})
261		}
262	}
263	
264	// TestGrantInvalidReceiverIDDoesNotHitReplacementCharReceiver 覆盖撞名场景：
265	// 已有一条属于标识中含合法 U+FFFD 的接收方的有效授权时，用一个只有该位置
266	// 换成坏字节的标识申请相同范围必须失败——不能被替换后归到那个接收方名下；
267	// 原授权的标识、范围、期限与可读取内容不变，关闭重开后也不会多出归属于
268	// 该接收方的授权。
269	func TestGrantInvalidReceiverIDDoesNotHitReplacementCharReceiver(t *testing.T) {
270		dir := t.TempDir()
271		clk := &fakeClock{t: time.Date(2026, 6, 3, 9, 0, 0, 0, time.UTC)}
272		open := func() *Store {
273			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
274			if err != nil {
275				t.Fatalf("open: %v", err)
276			}
277			return s
278		}
279	
280		s := open()
281		f := setupGrantUTF8(t, s)
282		st := clk.t.Add(-time.Hour)
283		en := clk.t.Add(24 * time.Hour)
284		scopes := []Scope{{EncounterID: f.eid, Category: Diagnosis}}
285	
286		// 用户明确输入合法 U+FFFD 的标识可以正常授权。
287		explicit := "接收-�"
288		a1, err := s.Grant(doc, f.pid, explicit, scopes, st, en)
289		if err != nil {
290			t.Fatalf("grant with explicit U+FFFD: %v", err)
291		}
292	
293		// 夹带非法字节的标识（替换后会变成 explicit）必须被拒绝，而不是
294		// 归到那个接收方名下：返回 ErrInvalidArgument，授权清单与审计不变。
295		auditBefore := mustAudit(t, s, f.pid)
296		bad := "接收-\xff"
297		for _, grant := range []func() (Authorization, error){
298			func() (Authorization, error) { return s.Grant(doc, f.pid, bad, scopes, st, en) },
299			func() (Authorization, error) {
300				return s.GrantSelective(doc, f.pid, bad, nil,
301					[]RecordSelection{{RecordID: f.rid, EncounterID: f.eid, Category: Diagnosis}}, st, en)
302			},
303		} {
304			a, err := grant()
305			if !errors.Is(err, ErrInvalidArgument) {
306				t.Fatalf("invalid utf8 receiver id err = %v, want ErrInvalidArgument", err)
307			}
308			if a.ID != "" {
309				t.Fatalf("rejected grant returned authorization %q", a.ID)
310			}
311		}
312		auths, err := s.ListAuthorizations(doc, f.pid, explicit)
313		if err != nil {
314			t.Fatal(err)
315		}
316		if len(auths) != 1 || auths[0].ID != a1.ID || auths[0].ReceiverID != explicit {
317			t.Fatalf("authorizations after rejected grant = %+v, want only %q", auths, explicit)
318		}
319		if !reflect.DeepEqual(auths[0].Scopes, a1.Scopes) ||
320			!auths[0].StartsAt.Equal(a1.StartsAt) || !auths[0].ExpiresAt.Equal(a1.ExpiresAt) {
321			t.Fatalf("original authorization changed: %+v, want %+v", auths[0], a1)
322		}
323		audit, err := s.AuditEvents(doc, f.pid)
324		if err != nil {
325			t.Fatal(err)
326		}
327		if !reflect.DeepEqual(audit, auditBefore) {
328			t.Fatalf("audit changed after rejected grant")
329		}
330	
331		// 原接收方可读取的内容不变。
332		res, err := s.Read(ReceiverActor(explicit), f.pid, f.eid, Diagnosis)
333		if err != nil {
334			t.Fatalf("read as original receiver: %v", err)
335		}
336		if len(res.Records) != 1 || res.Records[0].RecordID != f.rid {
337			t.Fatalf("read records = %+v, want record %q", res.Records, f.rid)
338		}
339	
340		// 关闭重开后仍只有那一条授权归属于该接收方，标识逐字相同。
341		s = reopenStore(t, s, dir, clk)
342		t.Cleanup(func() { _ = s.Close() })
343		auths, err = s.ListAuthorizations(doc, f.pid, explicit)
344		if err != nil {
345			t.Fatal(err)
346		}
347		if len(auths) != 1 || auths[0].ID != a1.ID || auths[0].ReceiverID != explicit {
348			t.Fatalf("authorizations after reopen = %+v, want only %q", auths, explicit)
349		}
350		all, err := s.ListAuthorizations(doc, f.pid, "")
351		if err != nil {
352			t.Fatal(err)
353		}
354		if len(all) != 1 {
355			t.Fatalf("extra authorizations appeared after reopen: %+v", all)
356		}
357	}
